export function getBuyerData(buyer: Buyer): BuyerData {
  return BUYER_LOOKUP[buyer];
}

export function getAnyCardData(card: string): AnyCardData {
  return CARD_LOOKUP[card] ?? BUYER_LOOKUP[card];
}

export function getCardColors(card: string): Color[] {
  const data = getAnyCardData(card);
  if (!data) return [];
  switch (data.kind) {
    case 'pigment': return data.colors;
    case 'starterPigment': return [data.color];
    case 'material': return data.color ? Array(data.colorCount ?? 1).fill(data.color) : [];
    case 'special': return [];
    case 'buyer': return [];
  }
}

